  String? get firstObserved => FIRST_OBSERVED;
  String? get LAST_OBSERVED => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 32);
  String? get lastObserved => LAST_OBSERVED;
  ///  Network operator name verbatim as the cited source states it. A display
  ///  name, never an identifier: consumers must not treat it as a stable key.
  String? get OPERATOR => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 34);
  ///  Operating centre frequency in MHz, following the $RFB convention. A
  ///  consumer joining to $IQC, which carries hertz, converts at the join,
  ///  explicitly. Zero means unpublished.
  double get FREQUENCY_MHZ => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 36, 0.0);
  double get frequencyMhz => FREQUENCY_MHZ;
  ///  Site or structure name verbatim when the source publishes one. Never
  ///  synthesized from coordinates, operator, or cell identity.
  String? get SITE_NAME => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 38);
  String? get siteName => SITE_NAME;
  ///  ISO 3166-1 alpha-2 country code, uppercase, as the source states it.
  ///  Derived from MCC only when the source itself derives it.
  String? get COUNTRY_CODE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 40);
  String? get countryCode => COUNTRY_CODE;
  ///  Every provider consulted for this site, including providers that returned
  ///  nothing. Required: a site with no named sources is not publishable.
  List<TBSProvenance>? get SOURCES => const fb.ListReader<TBSProvenance>(TBSProvenance.reader).vTableGetNullable(_bc, _bcOffset, 42);
  ///  How the entries in SOURCES were reduced to LATITUDE/LONGITUDE. Required:
  ///  a published position always states the rule that produced it, including
  ///  SINGLE_SOURCE.
  TBSConsensus? get CONSENSUS => TBSConsensus.reader.vTableGetNullable(_bc, _bcOffset, 44);

  @override
  String toString() {
    return 'TBS{ID: ${ID}, nativeId: ${nativeId}, RADIO: ${RADIO}, MCC: ${MCC}, MNC: ${MNC}, LAC: ${LAC}, TAC: ${TAC}, cellId: ${cellId}, LATITUDE: ${LATITUDE}, LONGITUDE: ${LONGITUDE}, rangeM: ${rangeM}, SAMPLES: ${SAMPLES}, averageSignalDbm: ${averageSignalDbm}, firstObserved: ${firstObserved}, lastObserved: ${lastObserved}, OPERATOR: ${OPERATOR}, frequencyMhz: ${frequencyMhz}, siteName: ${siteName}, countryCode: ${countryCode}, SOURCES: ${SOURCES}, CONSENSUS: ${CONSENSUS}}';
  }
}

class _TBSReader extends fb.TableReader<TBS> {
  const _TBSReader();

  @override
  TBS createObject(fb.BufferContext bc, int offset) =>
    TBS._(bc, offset);
}

class TBSBuilder {
  TBSBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(21);
  }

  int addIdOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addNativeIdOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }
  int addRadio(tbsRadioClass? RADIO) {
    fbBuilder.addInt8(2, RADIO?.value);
    return fbBuilder.offset;
  }
  int addMcc(int? MCC) {
    fbBuilder.addUint32(3, MCC);
    return fbBuilder.offset;
  }
  int addMnc(int? MNC) {
    fbBuilder.addUint32(4, MNC);
    return fbBuilder.offset;
  }
  int addLac(int? LAC) {
    fbBuilder.addUint32(5, LAC);
    return fbBuilder.offset;
  }
  int addTac(int? TAC) {
    fbBuilder.addUint32(6, TAC);
    return fbBuilder.offset;
  }
  int addCellIdOffset(int? offset) {
    fbBuilder.addOffset(7, offset);
    return fbBuilder.offset;
  }
  int addLatitude(double? LATITUDE) {
    fbBuilder.addFloat64(8, LATITUDE);
    return fbBuilder.offset;
  }
  int addLongitude(double? LONGITUDE) {
    fbBuilder.addFloat64(9, LONGITUDE);
    return fbBuilder.offset;
  }
  int addRangeM(double? RANGE_M) {
    fbBuilder.addFloat64(10, RANGE_M);
    return fbBuilder.offset;
  }
  int addSamples(int? SAMPLES) {
    fbBuilder.addUint32(11, SAMPLES);
    return fbBuilder.offset;
  }
  int addAverageSignalDbm(double? AVERAGE_SIGNAL_DBM) {
    fbBuilder.addFloat64(12, AVERAGE_SIGNAL_DBM);
    return fbBuilder.offset;
  }
  int addFirstObservedOffset(int? offset) {
    fbBuilder.addOffset(13, offset);
    return fbBuilder.offset;
  }
  int addLastObservedOffset(int? offset) {
    fbBuilder.addOffset(14, offset);
    return fbBuilder.offset;
  }
  int addOperatorOffset(int? offset) {
    fbBuilder.addOffset(15, offset);
    return fbBuilder.offset;
  }
  int addFrequencyMhz(double? FREQUENCY_MHZ) {
    fbBuilder.addFloat64(16, FREQUENCY_MHZ);
    return fbBuilder.offset;
  }
  int addSiteNameOffset(int? offset) {
    fbBuilder.addOffset(17, offset);
    return fbBuilder.offset;
  }
  int addCountryCodeOffset(int? offset) {
    fbBuilder.addOffset(18, offset);
    return fbBuilder.offset;
  }
  int addSourcesOffset(int? offset) {
    fbBuilder.addOffset(19, offset);
    return fbBuilder.offset;
  }
  int addConsensusOffset(int? offset) {
    fbBuilder.addOffset(20, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class TBSObjectBuilder extends fb.ObjectBuilder {
  final String? _ID;
  final String? _NATIVE_ID;
  final tbsRadioClass? _RADIO;
  final int? _MCC;
  final int? _MNC;
  final int? _LAC;
  final int? _TAC;
  final String? _CELL_ID;
  final double? _LATITUDE;
  final double? _LONGITUDE;
  final double? _RANGE_M;
  final int? _SAMPLES;
  final double? _AVERAGE_SIGNAL_DBM;
  final String? _FIRST_OBSERVED;
  final String? _LAST_OBSERVED;
  final String? _OPERATOR;
  final double? _FREQUENCY_MHZ;
  final String? _SITE_NAME;
  final String? _COUNTRY_CODE;
  final List<TBSProvenanceObjectBuilder>? _SOURCES;
  final TBSConsensusObjectBuilder? _CONSENSUS;

  TBSObjectBuilder({
    String? ID,
    String? NATIVE_ID,
    String? nativeId,
    tbsRadioClass? RADIO,
    int? MCC,
    int? MNC,
    int? LAC,
    int? TAC,
    String? CELL_ID,
    String? cellId,
    double? LATITUDE,
    double? LONGITUDE,
    double? RANGE_M,
    double? rangeM,
    int? SAMPLES,
    double? AVERAGE_SIGNAL_DBM,
    double? averageSignalDbm,
    String? FIRST_OBSERVED,
    String? firstObserved,
    String? LAST_OBSERVED,
    String? lastObserved,
    String? OPERATOR,
    double? FREQUENCY_MHZ,
    double? frequencyMhz,
    String? SITE_NAME,
    String? siteName,
    String? COUNTRY_CODE,
    String? countryCode,
    List<TBSProvenanceObjectBuilder>? SOURCES,
    TBSConsensusObjectBuilder? CONSENSUS,
  })
      : _ID = ID,
        _NATIVE_ID = nativeId ?? NATIVE_ID,
        _RADIO = RADIO,
        _MCC = MCC,
        _MNC = MNC,
        _LAC = LAC,
        _TAC = TAC,
        _CELL_ID = cellId ?? CELL_ID,
        _LATITUDE = LATITUDE,
        _LONGITUDE = LONGITUDE,
        _RANGE_M = rangeM ?? RANGE_M,
        _SAMPLES = SAMPLES,
        _AVERAGE_SIGNAL_DBM = averageSignalDbm ?? AVERAGE_SIGNAL_DBM,
        _FIRST_OBSERVED = firstObserved ?? FIRST_OBSERVED,
        _LAST_OBSERVED = lastObserved ?? LAST_OBSERVED,
        _OPERATOR = OPERATOR,
        _FREQUENCY_MHZ = frequencyMhz ?? FREQUENCY_MHZ,
        _SITE_NAME = siteName ?? SITE_NAME,
        _COUNTRY_CODE = countryCode ?? COUNTRY_CODE,
        _SOURCES = SOURCES,
        _CONSENSUS = CONSENSUS;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? IDOffset = _ID == null ? null
        : fbBuilder.writeString(_ID!);
    final int? NATIVE_IDOffset = _NATIVE_ID == null ? null
        : fbBuilder.writeString(_NATIVE_ID!);
    final int? CELL_IDOffset = _CELL_ID == null ? null
        : fbBuilder.writeString(_CELL_ID!);
    final int? FIRST_OBSERVEDOffset = _FIRST_OBSERVED == null ? null
        : fbBuilder.writeString(_FIRST_OBSERVED!);
    final int? LAST_OBSERVEDOffset = _LAST_OBSERVED == null ? null
        : fbBuilder.writeString(_LAST_OBSERVED!);
    final int? OPERATOROffset = _OPERATOR == null ? null
        : fbBuilder.writeString(_OPERATOR!);
    final int? SITE_NAMEOffset = _SITE_NAME == null ? null
        : fbBuilder.writeString(_SITE_NAME!);
    final int? COUNTRY_CODEOffset = _COUNTRY_CODE == null ? null
        : fbBuilder.writeString(_COUNTRY_CODE!);
    final int? SOURCESOffset = _SOURCES == null ? null
        : fbBuilder.writeList(_SOURCES!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? CONSENSUSOffset = _CONSENSUS?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(21);
    fbBuilder.addOffset(0, IDOffset);
    fbBuilder.addOffset(1, NATIVE_IDOffset);
    fbBuilder.addInt8(2, _RADIO?.value);
    fbBuilder.addUint32(3, _MCC);
    fbBuilder.addUint32(4, _MNC);
    fbBuilder.addUint32(5, _LAC);
    fbBuilder.addUint32(6, _TAC);
    fbBuilder.addOffset(7, CELL_IDOffset);
    fbBuilder.addFloat64(8, _LATITUDE);
    fbBuilder.addFloat64(9, _LONGITUDE);
    fbBuilder.addFloat64(10, _RANGE_M);
    fbBuilder.addUint32(11, _SAMPLES);
    fbBuilder.addFloat64(12, _AVERAGE_SIGNAL_DBM);
    fbBuilder.addOffset(13, FIRST_OBSERVEDOffset);
    fbBuilder.addOffset(14, LAST_OBSERVEDOffset);
    fbBuilder.addOffset(15, OPERATOROffset);
    fbBuilder.addFloat64(16, _FREQUENCY_MHZ);
    fbBuilder.addOffset(17, SITE_NAMEOffset);
    fbBuilder.addOffset(18, COUNTRY_CODEOffset);
    fbBuilder.addOffset(19, SOURCESOffset);
    fbBuilder.addOffset(20, CONSENSUSOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
